\label{gron}[Discrete Gronwall Lemma]
	Let $\gamma_i,\theta_i,\beta_i,\alpha_i$ (for $i\geq 0$), and $\Delta t$, C be a non-negative numbers such that
	\begin{eqnarray*}
		\gamma_M +\Delta t \sum_{i=0}^{M} \theta_i \leq \Delta t \sum_{i=0}^{M} \alpha_i\gamma_i +\Delta t \sum_{i=0}^{M} \beta_i + C,\, \, \forall M\geq 0.
	\end{eqnarray*}
	Assume $\alpha_i\Delta t <1$ for all $i$, then,
	\begin{eqnarray*}
		\gamma_M +\Delta t \sum_{i=0}^{M} \theta_i \leq \exp\Bigg(\Delta t \sum_{i=0}^{M}\theta_i \frac{\alpha_i}{1-\alpha_i\Delta t }\Bigg) \Bigg(\Delta t \sum_{i=0}^{M} \beta_i + C\Bigg),\, \, \forall M\geq 0.
	\end{eqnarray*}

